def flatten(d, prefix=''):
    out = {}
    for k, v in d.items():
        key = f'{prefix}{k}'
        if isinstance(v, dict): out.update(flatten(v, key + '.'))
        else: out[key] = v
    return out

fe, fh = flatten(EN), flatten(HI)
missing = sorted(set(fe) ^ set(fh))
assert not missing, f'en/hi keys differ: {missing}'
for name, data in (('en', EN), ('hi', HI)):
    with open(f'src/i18n/{name}.json', 'w') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write('\n')
print(f'{len(fe)} keys written for en + hi')
